import { normalizeRanges } from './normalize-ranges.mjs';

function validateEveryMember(ranges) {
  if (!Array.isArray(ranges)) {
    throw new TypeError('ranges must be an array');
  }
  for (const pair of ranges) {
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError('range must be an array of two numbers');
    }
    const start = pair[0];
    const end = pair[1];
    if (
      typeof start !== 'number' ||
      typeof end !== 'number' ||
      !Number.isFinite(start) ||
      !Number.isFinite(end)
    ) {
      throw new TypeError('range endpoints must be finite numbers');
    }
    if (start > end) {
      throw new RangeError('range start must be <= end');
    }
  }
}

export function subtractRanges(base, removed) {
  validateEveryMember(base);
  validateEveryMember(removed);
  let result = normalizeRanges(base);
  const cuts = normalizeRanges(removed);
  for (const [cutStart, cutEnd] of cuts) {
    const next = [];
    for (const [start, end] of result) {
      if (cutEnd <= start || cutStart >= end) {
        next.push([start, end]);
        continue;
      }
      if (start < cutStart) {
        next.push([start, cutStart]);
      }
      if (cutEnd < end) {
        next.push([cutEnd, end]);
      }
    }
    result = next;
  }
  return result.map(([start, end]) => [start, end]);
}

